import json, re, html
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
refs = json.loads(Path('reference-targets.json').read_text())
by_number = {s['number']: s for s in sources}
result = {}

def impact(classification, assessment, scope, burdens, effects=None):
    return dict(version=1, classification=classification, assessment=assessment,
                scope_limitations=scope, new_burdens_review=burdens, effects=effects or [])

def effect(kind, measure_id, description, before, after, unit, population, transition, replacement, source_quote, proposed_quote):
    return dict(kind=kind, measure_id=measure_id, description=description, before=before, after=after,
                unit=unit, affected_population=population, conditions_and_transition=transition,
                replacement_or_new_burdens=replacement, source_quote=source_quote, proposed_quote=proposed_quote)

def entry(n, reason, review, substantive, xml=None, removed=None):
    s=by_number[n]
    o={k:s[k] for k in ['code_id','source_id','source_sha256','number']}
    o.update(proposed_xml=xml, reason=reason, review_notes=review,
             status='retained_unchanged' if xml is None else 'rewrite_draft', substantive_impact=substantive)
    if xml is None:
        o['classification']='retained_necessary'
    if removed:
        o.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    result[n]=o
    return o

xml21="""<p>Les personnes mentionnées au premier alinéa de l'article L. 382-15 bénéficient de la prise en charge de leurs frais de santé dans les conditions prévues au livre Ier.</p>
<p>Les membres des congrégations et des collectivités religieuses bénéficient, sur leur demande, d'un régime particulier comportant des cotisations et des prestations réduites.</p>
<p>Ces prestations sont limitées à la couverture des frais d'hospitalisation et de traitement dans les établissements de soins et de cure publics et privés.</p>
<p>L'option pour le régime particulier peut être exercée lors de l'affiliation ou ultérieurement. Elle prend effet dès la réception de la demande, sans délai préalable, et demeure valable sans limitation de durée ni demande de renouvellement. Les intéressés peuvent demander à revenir au régime de droit commun ; ce retour prend effet dès la réception de leur demande.</p>
<p>Un décret détermine les modalités d'application des trois derniers alinéas ci-dessus. Il ne peut imposer de durée minimale d'option, de renouvellement périodique ou de délai préalable à sa prise d'effet ou au retour au régime de droit commun.</p>
<p>Ces dispositions s'appliquent aux demandes reçues à compter de l'entrée en vigueur de la loi portant la présente rédaction ainsi qu'aux demandes en cours à cette date, qui prennent effet au plus tôt à cette entrée en vigueur. Les options en cours se poursuivent sans renouvellement et peuvent prendre fin à la demande des intéressés dans les mêmes conditions. Les cotisations et prestations afférentes aux périodes antérieures, leurs régularisations, restitutions, prescriptions et recours demeurent régis par les dispositions antérieures, sans remboursement général ni double prise en charge.</p>"""
entry('L382-21',
"Réforme de fond : l'option pour le régime volontaire à cotisations et prestations réduites devient durable et révocable, sans renouvellement ni attente administrative. La durée de deux ans et la nouvelle demande trois mois avant son terme, précisées par D382-23, ne conditionnent plus le maintien de l'avantage. Le calendrier différé de D382-22 est également écarté expressément par la loi. Le champ des bénéficiaires, la couverture de droit commun et la limitation des prestations du régime réduit sont conservés intégralement ; aucune baisse supplémentaire de taux n'est inventée.",
"D382-22, D382-23 et D382-24 ont été lus intégralement dans le corpus public : coordonner leur calendrier et leur renvoi pour rendre l'option et le retour effectifs à réception. D382-25 fixe les cotisations à 61 % du droit commun : cette proportion n'est pas modifiée. La justification du paiement prévue par D382-24 n'est pas supprimée ici ; ce texte conserve par ailleurs une référence aux cotisations personnelles à confronter à l'abrogation du 1° de L382-22. Ne pas transformer la demande volontaire initiale en agrément supplémentaire ni subordonner la continuation à une attestation. Les prestations restent limitées à l'hospitalisation et au traitement dans les établissements de soins et de cure publics et privés. Les options anciennes deviennent continues pour l'avenir ; aucune reprise des anciens droits ni remboursement général.",
impact('material_reduction',
"Par rapport à l'article officiel entier, la durée déterminée renouvelable disparaît réellement. Le nouveau corps écarte aussi le calendrier réglementaire préalable et permet la sortie volontaire immédiate. Le régime favorable demeure ouvert aux demandes futures sans agrément ou renouvellement de remplacement.",
"Les taux et les prestations du régime réduit demeurent distincts du droit commun. Le délai réglementaire initial est documenté par D382-22, lu hors source assignée ; la citation source correspondante est son habilitation législative, qui ne chiffre pas ce délai. Aucun coût global ni effet national sur les recettes n'est établi.",
"Aucune charge nouvelle identifiée : la demande initiale existe déjà ; une demande de retour n'est exigée que si l'assuré choisit cette sortie. Aucun formulaire, justificatif, déclaration périodique ou registre nouveau ne remplace le renouvellement.",[
 effect('obligation_removed','cultes-option-regime-reduit-sans-attente-renouvellement',
 "Retrait du terme imposé et de la démarche périodique de renouvellement de l'option réduite.",
 "Option de durée déterminée renouvelable ; D382-23 impose deux ans et une nouvelle demande trois mois avant l'expiration.",
 "Option valable sans limitation de durée et sans renouvellement, avec retour volontaire au droit commun.",
 'legal_duty','Membres des congrégations et collectivités religieuses optant pour le régime particulier.',
 "Demandes nouvelles et en cours dès l'entrée en vigueur ; options en cours prolongées sans renouvellement ; périodes anciennes préservées.",
 "Aucun renouvellement tacitement conditionné, agrément, déclaration ou justificatif de remplacement.",
 "L'option pour le régime particulier est valable pour une durée déterminée ; elle est renouvelable.",
 "Elle prend effet dès la réception de la demande, sans délai préalable, et demeure valable sans limitation de durée ni demande de renouvellement."),
 effect('deadline_reduced','cultes-option-regime-reduit-sans-attente-renouvellement',
 "Retrait du calendrier différant la prise d'effet de l'option après affiliation.",
 "La loi délègue les modalités ; D382-22 lu impose, après affiliation, le premier jour du semestre suivant l'expiration de trois mois depuis la demande, soit une attente variable et non un nombre fixe de jours.",
 "Prise d'effet à réception de la demande ; aucun délai préalable ni attente de semestre.",
 'calendar_days','Membres déjà affiliés sollicitant le régime réduit ; aucune seconde économie de renouvellement comptée.',
 "Demandes nouvelles et en cours, sans effet antérieur à l'entrée en vigueur pour les demandes en cours ; anciens paiements non réouverts.",
 "Aucun délai, document ni autorisation de remplacement ; traitement administratif de la demande initiale existante.",
 "Un décret détermine les modalités d'application des trois derniers alinéas ci-dessus.",
 "Il ne peut imposer de durée minimale d'option, de renouvellement périodique ou de délai préalable à sa prise d'effet ou au retour au régime de droit commun.")]),xml21,[
 "Durée déterminée et demande périodique de renouvellement imposées pour conserver le régime particulier favorable.",
 "Attente réglementaire préalable et échéance semestrielle différant l'effet de l'option après l'affiliation.",
 "Maintien obligatoire de l'option pendant sa durée fixée avant le retour volontaire au régime de droit commun."])

xml211="""<p>I.-Les ministres des cultes bénéficient des indemnités journalières prévues à l'article L. 323-1 lorsque leur incapacité physique, constatée par le médecin traitant selon les règles définies par l'article L. 162-4-1, les met dans l'impossibilité de continuer ou de reprendre leur activité.<br /><br />
L'indemnité journalière est égale à une fraction de l'assiette des cotisations à la charge des associations, congrégations ou collectivités religieuses dont relève le ministre du culte.<br /><br />
Les indemnités journalières sont servies, à l'expiration d'un délai de carence et pour une durée maximale, sans condition de durée minimale d'affiliation. Le point de départ du délai de carence et la durée maximale de versement sont ceux prévus à l'article L. 323-1.<br /><br />
Les conditions prévues aux articles L. 323-4-1 à L. 323-6 sont applicables au versement des indemnités journalières. L'article L. 323-7 demeure applicable aux seules prescriptions antérieures à l'entrée en vigueur de son abrogation, dans les conditions transitoires prévues par cet article. Pour les prescriptions établies à compter de cette entrée en vigueur, une suspension antérieure des indemnités ne peut, à elle seule, subordonner la reprise de leur service à un avis préalable systématique du contrôle médical ; les autres conditions médicales et administratives, les contrôles, les suspensions justifiées et les recours demeurent applicables.<br /><br />
Un décret détermine les modalités d'application du présent I.<br /><br />
II.-Les ministres des cultes bénéficient des indemnités journalières prévues aux articles L. 331-3 à L. 331-8. L'indemnité journalière est égale à une fraction de l'assiette des cotisations à la charge des associations, congrégations ou collectivités religieuses dont relève le ministre du culte.</p>
<p>La suppression de la condition de durée minimale d'affiliation prévue au I s'applique aux indemnités dues pour les périodes courant à compter de l'entrée en vigueur de la loi portant cette suppression, y compris lorsque l'arrêt a commencé auparavant. Aucun justificatif de cette seule durée ne peut être exigé pour ces périodes. Les autres conditions propres aux prestations, les assimilations et dérogations plus favorables restent applicables aux situations antérieures et futures éligibles. Les prestations afférentes aux périodes antérieures, leurs créances, régularisations, restitutions, prescriptions et recours conservent leur régime, sans réouverture générale ni double paiement. Le II conserve les conditions et les dispositions transitoires propres aux prestations auxquelles il renvoie.</p>"""
entry('L382-21-1',
"Réforme de fond propre au régime des cultes et coordination : la condition autonome d'affiliation du I est expressément supprimée pour les périodes futures, car elle ajoute un délai à l'affiliation et à l'incapacité médicalement établies sans fonction essentielle démontrée. La réforme générale de L313-1 ne supprimait pas à elle seule cette condition spéciale, applicable ici même aux premiers jours indemnisables. L'allègement est rattaché à la même famille de mesure, sans compter une seconde réforme générale. Le renvoi à L323-7 est séparément limité à la transition de son abrogation. Les fractions d'assiette, la carence, la durée maximale, les protections maternité, adoption et paternité et les contrôles utiles demeurent ; aucun contrat de travail privé n'est créé pour le ministre du culte.",
"Cibles officielles et propositions fournies lues intégralement. L313-1 proposé comporte désormais un III : le renvoi ancien à son dernier alinéa ne désigne plus la condition d'affiliation. L323-7 proposé supprime le visa pour les nouvelles prescriptions seulement. Le champ continu L323-4-1 à L323-6 conserve préparation de reprise, limites de saisie et obligations de droit commun dans leurs rédactions coordonnées ; les propositions publiques de L323-4-1 et L323-6 ont été lues, sans nouvelle suppression comptée ici. L331-4, lu dans le corpus, conserve huit/dix-huit semaines et vingt-six semaines ; les cibles L331-3/5/6/7/8 maintiennent leurs autres durées et exceptions. D382-25-1, D382-25-2, D382-25-3 et R382-104-1 ont été lus : conserver 1/30,42, 50 %, 79 % et les transitions du 15 octobre 2026 dans leur champ. La carence spéciale de trente jours de D382-25-2, distincte de la durée d'affiliation, n'est pas réduite par cette coordination ; articulation législative/réglementaire à contrôler. La note du 1er juillet 2020 concerne le droit antérieur, pas la date future du projet.",
impact('material_reduction',
"Le corps entier conserve les deux catégories d'indemnités, retire expressément la condition spéciale d'affiliation des ministres des cultes et coordonne la fin du visa systématique de L323-7. La suppression spéciale vaut aussi pour le début d'indemnisation visé par le I, sans extension implicite du seul régime des salariés ni seconde baisse de cotisations revendiquée.",
"La carence et les durées maximales restent applicables. Les prestations anciennes et prescriptions anciennes gardent leur transition distincte. Le coût éventuel des prestations ouvertes et l'articulation de la carence spéciale de trente jours ne sont pas chiffrés ; pas d'extension du contrat unique aux activités cultuelles.",
"Aucune charge nouvelle identifiée : suppression de la seule preuve d'affiliation minimale et du visa correspondant au renvoi abrogé, sans formulaire ou déclaration de remplacement. La prescription médicale et les contrôles de droit commun restent ceux du dispositif existant.",[
 effect('obligation_removed','prestations-fin-minimum-affiliation-additionnel',
 "Supprimer expressément la condition spéciale d'affiliation des ministres des cultes, sous la même clé de mesure que le minimum général supprimé.",
 "Les IJ du I exigent la durée minimale d'affiliation de l'ancien dernier alinéa de L313-1.",
 "Pas de condition autonome de durée d'affiliation pour les périodes nouvelles ; autres conditions et ancien droit temporel conservés.",
 'legal_duty','Ministres des cultes bénéficiaires des indemnités du I.',
 "Périodes dues après entrée en vigueur, y compris arrêt commencé auparavant ; aucun paiement rétroactif général.",
 "Aucune preuve ou autorisation équivalente ; extension expresse au minimum spécial des cultes, dédupliquée sous la clé de la même mesure.",
 "Les indemnités journalières sont servies, à l'expiration d'un délai de carence et pour une durée maximale, aux assurés ayant la durée minimale d'affiliation prévue au dernier alinéa de l'article L. 313-1.",
 "Les indemnités journalières sont servies, à l'expiration d'un délai de carence et pour une durée maximale, sans condition de durée minimale d'affiliation."),
 effect('coordination','ij-nouvelle-prescription-fin-visa-systematique',
 "Limiter le renvoi à L323-7 aux anciennes prescriptions au lieu de rétablir son visa pour les nouvelles.",
 "Renvoi continu et sans réserve temporelle à L323-4-1 à L323-7 pour le versement des IJ.",
 "Renvoi actif jusqu'à L323-6 ; L323-7 seulement dans son champ transitoire ancien ; contrôle médical ordinaire conservé.",
 'legal_duty',"Ministres des cultes recevant une prescription après une suspension d'indemnités.",
 "Critère de date de prescription identique à L323-7 proposé ; anciennes périodes et décisions non annulées.",
 "Aucune formalité nouvelle ; la fin du visa constitue la même mesure que celle de L323-7.",
 "Les conditions prévues aux articles L. 323-4-1 à L. 323-7 sont applicables au versement des indemnités journalières.",
 "L'article L. 323-7 demeure applicable aux seules prescriptions antérieures à l'entrée en vigueur de son abrogation, dans les conditions transitoires prévues par cet article.")]),xml211,["Condition autonome de durée minimale d'affiliation imposée aux ministres des cultes pour l'ensemble des indemnités du I."])

entry('L382-22',
"Maintien nécessaire après examen : la cotisation forfaitaire des associations et la contribution subsidiaire du régime général financent la couverture maladie maintenue par L382-21. Ce ne sont ni un prélèvement accessoire sans objet ni un double dépôt. Le 1° déjà abrogé n'est pas une nouvelle suppression. La répartition favorable selon les capacités contributives demeure ouverte par le renvoi au second alinéa du II de L382-25.",
"Contrôle du renvoi interne : le second alinéa du II de L382-25 est bien la répartition sur demande des représentants des cultes, non la fixation des taux. La réforme de l'option de L382-21 ne supprime pas le financement du régime réduit ; la proportion réglementaire de 61 % lue à D382-25 demeure. Aucun transfert vers la capitalisation des salariés privés ni aucune recette de compensation ne sont étendus ici.",
impact('retained_necessary',
"Le texte entier est utile au financement de la couverture maladie des cultes, avec un financeur associatif identifié et un concours subsidiaire du régime général. Aucune obligation déclarative ou autorisation autonome n'est ajoutée par cet article et la répartition favorable est conservée.",
"Le montant et le taux relèvent du règlement et ne sont pas évalués dans cet article. Leur suppression sans dispositif de financement aurait un effet non établi sur les droits ; aucune réduction nationale de prélèvement ni économie n'est démontrée.",
"Aucune charge nouvelle identifiée : maintien intégral de la cotisation existante et de la faculté de répartition, sans nouvelle donnée, demande périodique ou justificatif. Le 1° abrogé demeure sans effet."))

entry('L382-23',
"Maintien nécessaire : cette habilitation permet de coordonner l'affiliation des ministres des cultes et membres des congrégations exerçant une activité à temps partiel avec leur autre régime obligatoire. Elle protège l'accès aux prestations et évite de confondre cette pluralité d'activités avec une durée déterminée de l'emploi. Aucune déclaration, pièce ou autorisation individuelle supplémentaire n'est instituée par le texte.",
"R382-57 lu dans le corpus précise le régime obligatoire concurrent et le seuil propre d'activité partielle ; le dispositif concerne les conditions d'affiliation et non le minimum général de vingt-quatre heures supprimé pour les contrats de travail. Aucun renvoi n'est créé vers L3123-7 du code du travail. Les conditions plus favorables et situations futures éligibles restent ouvertes.",
impact('retained_necessary',
"La norme entière reste l'articulation législative des protections sociales en cas d'activité partielle relevant d'un autre régime. Son retrait pourrait fermer une couverture ou produire un conflit d'affiliation ; aucun doublon de formalité n'est identifié dans ce texte.",
"Le contenu détaillé des conditions réglementaires n'est pas réécrit dans cet article et aucun solde de cotisations entre régimes n'est établi. La suppression du minimum horaire privé n'est pas une extension automatique de l'affiliation cultuelle.",
"Aucune charge nouvelle identifiée : l'habilitation existante est conservée sans nouvelle déclaration, justificatif ni renouvellement. Aucun emploi nouveau à durée déterminée n'est autorisé."))

xml24="""<p>Les ministres des cultes et les membres des congrégations et collectivités religieuses mentionnés à l'article L. 382-15 ont droit à une pension d'invalidité lorsque leur état de santé les met dans l'incapacité totale ou partielle d'exercer, médicalement constatée. Aucun réexamen médical ne peut être imposé au seul motif de l'expiration d'une période déterminée. Les contrôles médicaux nécessaires à la vérification de l'incapacité et la révision de la pension en fonction de l'état médicalement constaté demeurent applicables.</p>
<p>Un décret détermine les modalités de calcul du montant de la pension.</p>
<p>La pension d'invalidité est remplacée, à l'âge fixé en application de l'article L. 351-1-5, par la pension de vieillesse prévue à la sous-section 4 de la présente section.</p>
<p>La pension d'invalidité est majorée d'un montant fixé par décret lorsque le titulaire se trouve dans l'obligation d'avoir recours à l'aide constante d'une tierce personne pour accomplir les actes ordinaires de la vie.</p>
<p>La suppression du réexamen médical périodique systématique s'applique à compter de l'entrée en vigueur de la loi portant la présente rédaction, y compris aux pensions en cours de service. Elle ne fait pas obstacle à l'examen d'une demande de révision ni aux contrôles médicaux nécessaires et ne subordonne pas le maintien de la pension à une attestation périodique de remplacement. Les droits, décisions, créances, régularisations, restitutions, prescriptions et recours relatifs aux périodes antérieures conservent leur régime, sans réouverture générale.</p>"""
entry('L382-24',
"Réforme de fond ciblée : retrait de la révision médicale imposée du seul fait d'une périodicité réglementaire. La constatation de l'incapacité totale ou partielle, les contrôles médicaux utiles et la révision justifiée par l'état de santé restent possibles. Le montant réglementaire, le remplacement par la vieillesse à l'âge spécial de L351-1-5 et la majoration de tierce personne sont intégralement conservés, sans modification des quatre alinéas de rattachement.",
"L351-1 fourni et L351-1-5 lu dans le corpus : préserver l'âge abaissé pour inaptitude/incapacité, sans le remplacer par l'âge ordinaire. D382-26 et D382-31 ont été lus : barèmes 30/50/50 %, minimum et validation des périodes restent hors de la coupe. R382-106 à R382-118 ont été lus : coordonner le caractère temporaire de R382-114 avec la suppression du seul réexamen systématique, préserver classement et dates favorables de R382-117, revalorisation R382-116 et présomption favorable R382-109. Incohérences préexistantes à contrôler séparément : R382-107 vise encore le 1° abrogé de L382-22 et R382-110/113 mentionnent le soixantième anniversaire. Aucune correction implicite de ces règles ni généralisation de la capitalisation privée. La note du 1er septembre 2023 conserve son champ historique.",
impact('material_reduction',
"La source entière impose une incapacité médicalement constatée et révisée périodiquement ; seule cette dernière automaticité est retirée. Les contrôles nécessaires, les catégories de pension, le passage à la vieillesse et la majoration pour tierce personne restent opposables ou ouverts, y compris pour les futurs bénéficiaires.",
"Le nombre de réexamens évités, le coût public et les fréquences réglementaires effectives ne sont pas chiffrés. La réforme ne supprime pas les contrôles ni les conditions d'invalidité ; les incohérences réglementaires anciennes identifiées demeurent à coordonner dans leurs propres articles.",
"Aucune charge nouvelle identifiée : aucune attestation périodique, déclaration de stabilité, registre ou nouvelle consultation obligatoire ne remplace le réexamen automatique. Les examens nécessaires relèvent des pouvoirs médicaux existants.",[
 effect('obligation_removed','cultes-invalidite-fin-reexamen-periodique-systematique',
 "Supprimer le réexamen médical imposé par la seule échéance périodique de l'invalidité.",
 "Incapacité totale ou partielle médicalement constatée et révisée selon une périodicité fixée par décret.",
 "Constatation initiale et contrôles nécessaires conservés ; aucune révision médicale exigée au seul écoulement d'un délai.",
 'legal_duty',"Ministres des cultes et membres des congrégations ou collectivités religieuses titulaires ou demandeurs d'une pension d'invalidité.",
 "Application dès l'entrée en vigueur, y compris pensions en cours ; anciens droits et recours préservés.",
 "Aucune attestation ou démarche périodique de remplacement ; contrôles et demandes volontaires de révision conservés.",
 "Les ministres des cultes et les membres des congrégations et collectivités religieuses mentionnés à l'article L. 382-15 ont droit à une pension d'invalidité lorsque leur état de santé les met dans l'incapacité totale ou partielle d'exercer, médicalement constatée et révisée selon une périodicité fixée par décret.",
 "Aucun réexamen médical ne peut être imposé au seul motif de l'expiration d'une période déterminée.")]),xml24,["Réexamen médical systématique de l'incapacité déclenché par une périodicité fixée par décret, indépendamment d'un besoin de contrôle."])

entry('L382-25',
"Maintien nécessaire : les cotisations forfaitaires des assurés et organismes, concours de la branche vieillesse, recettes diverses et contribution subsidiaire de la CNAV financent la pension de la présente sous-section. Leur suppression serait une suppression de financement principal sans démonstration de doublon. L'avis du conseil représentant les cultes garantit leur participation à la fixation des paramètres. La répartition selon les capacités contributives est un avantage collectif maintenu, pour les situations futures comme antérieures.",
"Le second alinéa du II demeure à sa place : L382-22 le vise expressément. Les subdivisions 1° à 6°, dont le 3° déjà abrogé, restent intactes. L222-2-1 fourni confirme le financement de solidarité de la branche ; ne pas réintroduire un CDD par ses renvois de formation. La note législative 2025-199 fixe le 1er janvier 2026 pour la réforme ancienne du financement, et non pour le présent projet. Aucun transfert de ces cotisations cultuelles dans le mécanisme réservé aux salariés privés de L241-3.",
impact('retained_necessary',
"La source entière organise le financement vieillesse et une modulation entre organismes selon leurs capacités, sans dépôt déclaratif supplémentaire identifié. Les recettes principales et la participation du conseil demeurent nécessaires aux droits maintenus ; aucune suppression effective n'est revendiquée.",
"Les taux forfaitaires réglementaires, l'équilibre financier du régime et l'exercice effectif de la répartition ne sont pas chiffrés. Le premier champ de la capitalisation des salariés privés ne couvre pas automatiquement les assurés du régime des cultes.",
"Aucune charge nouvelle identifiée : conservation intégrale des financeurs, de l'avis existant et de la répartition facultative ; aucune nouvelle pièce, déclaration, autorisation ou période minimale n'est créée."))

entry('L382-26',
"Maintien intégral d'un avantage nécessaire : la majoration pour tierce personne peut compléter la pension de vieillesse tant lorsque les conditions sont remplies à la liquidation que lorsqu'elles le deviennent ultérieurement avant l'âge réglementaire. Supprimer cette articulation fermerait un droit futur. Elle ne prescrit ni demande périodique ni justificatif redondant dans son propre texte.",
"Le renvoi à L382-24 continue de viser l'incapacité et la majoration maintenues, malgré la suppression de la révision médicale périodique dans cet article. Conserver les deux moments d'ouverture et la limite d'âge réglementaire sans inventer d'âge chiffré. Il ne s'agit ni d'un impôt au décès ni d'une indemnité ordinaire de rupture.",
impact('retained_necessary',
"Le texte entier protège l'accès à une majoration indispensable à l'assistance d'une tierce personne, à la liquidation et pour les besoins apparus ensuite dans la limite d'âge prévue. Aucun prélèvement accessoire ni doublon documentaire autonome n'est identifié.",
"Le montant et l'âge sont réglementaires et ne sont ni modifiés ni évalués ici. Aucun nouveau droit au-delà de cette limite n'est affirmé et aucun coût national de la majoration n'est chiffré.",
"Aucune charge nouvelle identifiée : maintien du seul droit et de ses conditions existantes, sans certificat périodique, demande de renouvellement ou registre nouveau."))

entry('L382-27',
"Maintien nécessaire de l'intégralité de l'ouverture de la pension des cultes et de ses renvois aux départs anticipés, périodes assimilées, majorations, minima, réversion et garanties de paiement. L'alinéa sur les périodes antérieures à 1998 protège des droits historiques encore applicables. Les cotisations vieillesse ne sont pas transférées automatiquement vers la capitalisation des salariés privés ; aucune réduction réelle ne résulterait d'un simple changement de mots.",
"Les cibles L351-1, L351-3, L351-10 et L355-3 ont été lues dans leurs textes entiers fournis. Le renvoi vise les seuls 4°, 5° et 6° de L351-3 : service national, situations de guerre et détention provisoire, pas toutes ses catégories. Conserver 1er janvier 1998, 31 décembre 1997 et l'ancien L721-6 dans son champ historique. Anomalie source signalée sans correction silencieuse : le texte dit que les prestations antérieures sont « indiquées » ; ne pas lui attribuer une formule de liquidation différente. L351-11 et L161-23-1 ont été lus dans le corpus, sources et propositions entières : L351-11 concerne les cotisations et salaires de base et sa proposition conserve leur revalorisation au I de L161-23-1. Le renvoi historique du présent article fait bénéficier les minimum et maximum anciens de ces conditions, sans gel nouveau de leurs barèmes. Le II proposé de L161-23-1 vise séparément les seules pensions de vieillesse et de réversion effectivement servies, au-dessus d'un seuil cumulé revalorisé, pendant au plus trois ans à compter du premier transfert, non l'invalidité ni les bases salariales. Le contenu historique de L721-6 n'est pas reproduit par le corpus actuel ; aucune formule nouvelle n'en est déduite ni filiation non documentée déclarée achevée.",
impact('retained_necessary',
"La norme entière assure aux cultes un ensemble de droits de pension et maintient des droits antérieurs à 1998. La liste n'est pas un doublon de déclaration : elle rend les garanties du régime général applicables au régime spécial sans supprimer ses antécédents.",
"Le renvoi actuel à L351-11 a été lu ; la formulation « indiquées » et le contenu historique de L721-6 demeurent des points documentaires signalés, sans filiation incertaine présentée comme achevée. Les paramètres de pension et le coût consolidé ne sont pas recalculés ; la capitalisation privée n'est pas étendue.",
"Aucune charge nouvelle identifiée : aucun justificatif, déclaration, notification d'emploi ou suivi d'actifs n'est ajouté aux règles conservées. Les renvois maintiennent les protections et leur champ propre."))

entry('L382-28',
"Maintien nécessaire de la transition entre les allocations des régimes de prévoyance antérieurs et la pension légale. Cette habilitation conserve le raccordement des situations historiques et prévient une interruption ou un double service sans éteindre une créance ancienne. L'article n'impose aucune formalité individuelle ni prélèvement accessoire pouvant être retiré isolément.",
"La substitution concerne les régimes antérieurs de prévoyance des cultes et non le passage futur à une capitalisation des salariés privés. Aucun nouveau délai, terme de contrat ou date de bascule n'est ajouté ; vérifier les textes anciens d'exécution pour toute liquidation concrète sans les présumer abrogés.",
impact('retained_necessary',
"La source entière est une règle de raccordement de prestations anciennes encore potentiellement applicable. Son maintien protège les bénéficiaires et n'est compté ni comme réécriture ni comme suppression d'une obligation.",
"Le stock des allocations historiques, les textes réglementaires de substitution et leur coût ne sont pas reconstitués dans ce lot. Aucun achèvement d'un audit des anciens régimes ni économie nationale n'est affirmé.",
"Aucune charge nouvelle identifiée : l'habilitation existante reste intacte et aucune procédure de conversion, attestation ou demande supplémentaire n'est instituée."))

old29=by_number['L382-29']['source_xml']
list29="""Les dispositions des articles L. 173-7, L. 216-1, L. 114-10, L. 217-1, L. 217-2, L. 231-5, L. 231-12, L. 243-4 à L. 243-6, L. 244-1 à L. 244-4, L. 244-7, L. 244-8-1, L. 244-9 et L. 244-10, L. 244-14, L. 256-3, L. 256-4, L. 272-1, L. 281-3, L. 351-14-1, L. 355-2, L. 355-3, L. 377-2 et L. 377-4 sont applicables, dans la mesure où elles ne sont pas contraires aux dispositions de la présente section, aux personnes, collectivités ou organismes mentionnés à la présente section."""
trans29="""Les articles L. 244-5, L. 244-13 et L. 272-2 ne demeurent applicables que dans les limites temporelles et matérielles expressément conservées par leurs dispositions d'abrogation respectives. Leur ancien renvoi par la présente section ne peut rétablir, pour l'avenir, la publication ou l'affichage aux frais du contrevenant, la nullité ou l'interdiction de l'assistance rémunérée à une demande de remise, ni les maxima obligatoires et la publicité spéciale supprimés. Les dispositions répressives plus douces et les règles d'application de la loi pénale dans le temps demeurent applicables ; les effets civils des conventions antérieures sont conservés dans les conditions de l'article L. 244-13."""
xml29='<p>'+list29+'</p>\n<p>'+trans29+"</p>\n<p>La suppression du renvoi à l'article L. 256-1 ne porte atteinte à aucune règle de comptabilité ou de gestion financière applicable aux organismes de la présente section sur un fondement autonome.</p>"
source29=html.unescape(re.sub('<[^>]+>','',old29)).strip()
entry('L382-29',
"Coordination nécessaire de la liste de renvois : ne plus faire appliquer pour l'avenir L244-5, L244-13 et L272-2 dont les propositions publiques portent l'abrogation, tout en conservant expressément leurs transitions et la loi pénale plus douce. Le renvoi à L256-1, sans cible active dans le corpus fourni, est retiré sans inventer un successeur ; les règles financières autonomes sont réservées. Tous les autres renvois utiles, la réserve de compatibilité et les garanties de remboursement, de remise et de recours demeurent. Aucune de ces coordinations n'est une seconde suppression de taxe, de sanction ou de procédure.",
"Les textes et propositions de L244-5, L244-13 et L272-2 ont été lus intégralement dans le corpus public. Les dates sont celles de leurs abrogations respectives, sans rétroactivité générale ; les conventions anciennes, condamnations définitives et dispositions pénales plus douces gardent leur champ. L256-1 est absent du corpus public accessible : filiation et date d'abrogation non établies ici, aucune référence de remplacement inventée et aucun volet documentaire prétendu achevé. Les sources et propositions publiques de L217-1, L231-5, L243-4, L243-6, L244-2 et L244-4 ont également été lues : leurs allègements restent applicables selon leurs propres transitions, sans seconde réduction comptée. L256-4 conserve les remises de précarité présentes et futures et ses créances anciennes. Les contrôles et incriminations de fraude de L114-10/L272-1 ainsi que la protection des conflits d'intérêts de L244-14 ne sont pas supprimés. La note de contrôle au 1er janvier 2017 n'est pas une date de la réforme future.",
impact('coordination_only',
"La liste entière est coordonnée pour ne pas faire revivre trois dispositifs déjà supprimés dans leurs articles propres. Les droits de remboursement, remises, prescriptions, défense et recours ainsi que les contrôles et infractions distincts sont conservés ; le retrait du renvoi non résolu à L256-1 n'est crédité d'aucun gain matériel.",
"Les effets des trois abrogations sont dédupliqués sous leurs clés existantes. L'historique exact de L256-1 n'est pas démontré par le corpus fourni ; les règles autonomes de comptabilité sont préservées sans prétendre en avoir achevé la concordance. Aucun chiffrage de coût ou solde national n'est établi.",
"Aucune charge nouvelle identifiée : aucun contrôle, délai de recours, autorisation de conseil ou déclaration ne remplace les règles supprimées. La clause financière ne crée pas de régime ni de pièce nouvelle et réserve seulement les fondements légaux autonomes.",[
 effect('coordination',mid,desc,bef,aft,'legal_duty',pop,
 "Application selon les transitions de l'article fondateur ; situations antérieures et loi pénale plus douce conservées.",
 "Aucun nouveau dispositif ni seconde réduction ; maintien des seuls fondements autonomes applicables.",source29,trans29)
 for mid,desc,bef,aft,pop in [
 ('recouvrement-social-fin-publication-payante',"Retirer le renvoi actif à la publication et à l'affichage payants de L244-5.","La plage L244-1 à L244-5 applique aussi la faculté de publicité payante aux personnes de la section.","Plage active arrêtée à L244-4 ; L244-5 seulement dans ses effets transitoires.","Personnes, collectivités et organismes du régime des cultes concernés par le recouvrement."),
 ('remises-sociales-fin-interdiction-generale-intermediaires',"Coordonner l'abrogation de la nullité et de l'interdiction générale d'assistance rémunérée de L244-13.","Renvoi général à L244-13 pour l'assistance rémunérée en vue d'une remise.","Absence de rétablissement futur de l'interdiction ; contrats anciens et règles autonomes préservés.","Cotisants et intermédiaires dans le champ du régime des cultes."),
 ('fraude-sociale-fin-maxima-obligatoires-publicite-speciale',"Coordonner la suppression de l'automaticité des maxima et de la publicité spéciale de L272-2.","Renvoi conjoint à L272-1 et L272-2, y compris maxima obligatoires et publicité spéciale.","L272-1 demeure actif ; L272-2 est limité aux règles transitoires de son abrogation.","Responsables et agents des organismes concernés par la section, sans dépénalisation de la fraude.")]]),xml29)

entry('L382-29-1',
"Maintien intégral de la faculté favorable de prise en compte des formations religieuses antérieures à l'affiliation, selon les mêmes conditions que les études du 1° du I de L351-14-1. Une formation limitée dans le temps ne crée ni contrat de travail ni CDD. Aucune formalité de renouvellement, déclaration autonome ou cotisation accessoire n'est imposée par cet article ; le versement de rachat est facultatif et ouvre des droits.",
"L351-14-1 entier fourni maintient douze trimestres au total, neutralité actuarielle et réductions des II, III et IV dans leurs champs. Sa proposition écarte la catégorie administrative d'établissement sans supprimer diplôme ou scolarité assimilée ; le renvoi reste au 1° du I et ne rétablit pas cette catégorie pour les demandes nouvelles ou en cours. Ne pas réserver la possibilité à des formations déjà achevées avant la réforme ni étendre automatiquement toutes les réductions à toute formation cultuelle. La formation doit précéder le statut entraînant affiliation, comme dans la source.",
impact('retained_necessary',
"La source entière est une extension favorable de la prise en compte de formations, à conserver pour les situations futures éligibles. Le rachat volontaire et ses garanties ne sont pas un prélèvement obligatoire accessoire à supprimer ; aucune simplification autonome n'est revendiquée.",
"Le tarif du rachat, les conditions de chaque réduction et les effets sur une pension donnée ne sont pas chiffrés. Les périodes restent antérieures à l'affiliation cultuelle et la formation n'est pas assimilée à un nouveau contrat d'emploi.",
"Aucune charge nouvelle identifiée : le renvoi existant et la faculté de rachat restent inchangés, sans nouvelle attestation de formation, condition de contrat ou démarche périodique."))

entry('L382-30',
"Maintien nécessaire de l'adhésion volontaire vieillesse offerte aux ministres des cultes et membres des congrégations et collectivités religieuses français exerçant à l'étranger ou outre-mer. Supprimer ce texte fermerait l'accès à la protection plutôt que retirer une obligation. Le critère de nationalité délimite cette affiliation volontaire extraterritoriale ; aucune obligation générale de cotiser ni déclaration répétée ne résulte de l'article.",
"Ne pas transformer l'adhésion facultative en affiliation obligatoire ni fermer l'accès aux futurs assurés éligibles. Les accords internationaux et les régimes territoriaux distincts ne sont pas réputés supprimés ou unifiés par cet article. Une extension de l'adhésion à toute activité cultuelle étrangère sans rattachement défini ne peut être déduite de la réforme des salariés privés.",
impact('retained_necessary',
"La disposition entière conserve un droit d'adhésion volontaire vieillesse au-delà du territoire ordinaire d'affiliation. Aucune taxe ou formalité périodique autonome n'est identifiée ; son retrait serait une perte d'accès à l'assurance.",
"Le raccordement aux conventions internationales, aux autres régimes territoriaux et le coût d'une extension de population ne sont pas établis ici. La nationalité et l'exercice hors territoire conservent leur champ source sans extension mondiale implicite.",
"Aucune charge nouvelle identifiée : maintien de la seule possibilité d'adhésion existante, sans agrément ou justificatif nouveau ni cotisation imposée aux personnes qui n'y adhèrent pas."))

entry('L382-31',
"Maintien nécessaire de l'affiliation des élus locaux, du seuil d'assujettissement de leurs indemnités, de l'exception protégeant ceux qui ont cessé leur activité et de l'option volontaire des élus sous le seuil. Le seuil est un allègement conservé pour les situations futures ; supprimer les deux derniers alinéas priverait certains élus de couverture ou d'une possibilité de constituer des droits. Les cotisations financent l'ensemble des risques et ne sont pas des accessoires sans fonction identifiée.",
"Ne pas confondre les articles du CGCT cités au deuxième alinéa avec leurs homonymes du code du travail : la cible fournie L3123-7 du travail n'est pas le L3123-7 du CGCT réellement visé. Texte intégral du CGCT non fourni dans ce contexte ; aucun remplacement de code ou délai privé n'est inventé. Le renvoi à L241-3 vise la valeur du plafond, non son nouveau mécanisme de capitalisation. Conserver la différence entre montant total supérieur au seuil, exception au montant inférieur et option des indemnités non assujetties ; ne pas réécrire silencieusement les bornes. Le mandat public n'est ni un CDI ni un CDD.",
impact('retained_necessary',
"La source entière combine affiliation, cotisations au-delà d'un seuil, couverture des élus sans autre activité et cotisation volontaire sous le seuil. Ces règles ont des fonctions distinctes et l'allègement sur les petites indemnités demeure applicable ; aucune coupe démontrée n'est comptée.",
"La fraction réglementaire du plafond et les règles du CGCT ne sont pas recalibrées. Le texte intégral des cibles CGCT n'est pas fourni ; l'homonymie avec L3123-7 du travail n'est pas une concordance. Aucune économie ou baisse nette de prélèvement n'est établie.",
"Aucune charge nouvelle identifiée : l'affiliation et la demande facultative restent celles de la source ; aucun préavis d'emploi, justificatif de cessation ou déclaration périodique supplémentaire n'est ajouté."))

entry('L382-32',
"Maintien nécessaire : l'activité professionnelle exercée dans les conditions des travailleurs libres conserve son propre régime pour la semi-liberté, le placement extérieur et la détention à domicile sous surveillance électronique. L'exception de L382-43 pour maternité, invalidité et décès reste applicable aux seules mesures de semi-liberté et de placement extérieur visées au deuxième alinéa. L'article évite un conflit d'affiliation et protège la continuité des droits, sans prélèvement supplémentaire autonome.",
"L382-43 a été lu dans le corpus public : prise en compte du travail pénitentiaire et des stages, avec maintien et coordination L161-8/L172-1 à L172-3. Les renvois 723 et 723-7 visent le code de procédure pénale ; leurs textes ne sont pas fournis et aucune nouvelle concordance n'est inventée. Si l'emploi extérieur est de droit privé, sa forme et sa rupture relèvent de ses règles propres et de la transition des anciens contrats ; cette exclusion de la section ne recrée aucun CDD ni aucune durée d'emploi liée à la peine.",
impact('retained_necessary',
"Le texte officiel entier est une articulation nécessaire entre l'assurance d'une activité extérieure libre et les protections liées à la détention. Les deux alinéas n'ont pas le même champ de mesures pénales ; leur maintien évite de fermer les avantages de maternité, invalidité et décès.",
"Les cibles du code de procédure pénale ne sont pas reproduites dans les données assignées et aucune validation exhaustive de leurs modifications ultérieures n'est affirmée. L'article ne définit pas la forme du contrat extérieur ni le coût de son affiliation.",
"Aucune charge nouvelle identifiée : aucun dossier, délai ou déclaration ne remplace une affiliation ; les conditions d'ouverture propres au régime d'activité et l'exception existante sont maintenues."))

entry('L382-33',
"Maintien intégral nécessaire de l'affiliation des personnes écrouées pour tous les risques et de la dérogation à la condition de régularité du séjour. Cette dérogation favorable doit rester ouverte aux futurs écrous ; la supprimer sous couvert d'allègement fermerait la protection sociale. L'article n'impose ni agrément, déclaration personnelle ni justificatif supplémentaire.",
"L115-6 lu dans le corpus subordonne en principe l'affiliation des étrangers à la régularité du séjour ; la dérogation du présent article est donc opérante et autonome. Ne pas la confondre avec les conditions AT-MP distinctes de L412-8, ni avec les règles de prestations en espèces. Aucun transfert à la capitalisation des salariés privés n'est déduit de l'affiliation générale.",
impact('retained_necessary',
"La source entière fonde une protection sociale essentielle et une dérogation favorable à la condition de séjour. Aucune obligation personnelle redondante ni taxe accessoire n'y est identifiée ; l'affiliation ne saurait être retirée sans fermer des droits.",
"Les modalités pratiques d'affiliation et les prestations de chaque risque restent dans leurs textes propres. L'article ne démontre ni un coût national ni une extension de tous les régimes spéciaux, notamment AT-MP.",
"Aucune charge nouvelle identifiée : maintien du droit et de la dérogation existants, sans nouvelle attestation de séjour, demande d'agrément ou déclaration par la personne écrouée."))

xml34="""<p>Les personnes écrouées, y compris lorsqu'elles ne remplissent pas la condition mentionnée à l'article L. 115-6, bénéficient de la prise en charge de leurs frais de santé, assurée par le régime général à compter de la date de leur mise sous écrou. Pendant toute la durée du séjour auprès de leur mère écrouée, les enfants nés au cours de la détention bénéficient de la prise en charge des frais de santé dans les mêmes conditions.<br /><br />
Aucune participation ne peut être demandée aux personnes écrouées sur le fondement du présent article au titre de la prise en charge des frais de santé prévue au premier alinéa, quel que soit le montant de leurs ressources.<br /><br />
Les conditions d'application du présent article sont déterminées par décret en Conseil d'Etat.</p>
<p>La suppression de la participation s'applique aux frais de santé afférents aux soins dispensés à compter de l'entrée en vigueur de la loi portant la présente rédaction, y compris lorsque la mise sous écrou est antérieure. Elle s'applique également, par le renvoi de l'article L. 382-37, aux personnes retenues dans un centre socio-médico-judiciaire de sûreté. Aucune cotisation, déclaration de ressources ou participation de remplacement ne peut être instituée sur ce fondement. Les créances légalement nées au titre des soins antérieurs, leurs exonérations et limitations, régularisations, restitutions, prescriptions et recours conservent leur régime, sans remboursement général des sommes légalement dues.</p>"""
entry('L382-34',
"Réforme de fond : suppression de la faculté de demander aux personnes écrouées disposant de ressources suffisantes une participation spéciale à leurs frais de santé. Cette participation accessoire ne conditionne pas l'accès aux soins et son maintien n'est pas nécessaire à l'affiliation. Le droit dès la mise sous écrou, la dérogation de séjour et la couverture des enfants nés pendant la détention demeurent intégralement. La suppression vaut également pour les personnes retenues par le renvoi de L382-37.",
"Les trois alinéas du corps initial conservent leur emplacement ; seul le deuxième retire la participation, suivi d'une transition autonome. L382-35 conserve la dispense d'avance et la prise en charge du ticket modérateur et du forfait journalier : aucune contradiction ni participation équivalente ne doit être recréée par le décret. Ne pas étendre la suppression aux cotisations sur les rémunérations ou aux dépenses d'entretien de la détention ayant un fondement autonome. Le texte source ne fournit ni taux ni assiette chiffrée de cette participation facultative ; sa perception effective et la perte de recettes ne sont pas présumées établies. Aucune compensation fiscale n'est inventée.",
impact('material_reduction',
"La source entière autorise une participation sanitaire spéciale selon les ressources ; ce pouvoir est effectivement retiré pour les soins futurs, sans condition de ressources de remplacement. Les garanties sanitaires de la mère, de l'enfant et des personnes sans séjour régulier sont maintenues ; le gain monétaire effectif dépend des participations auparavant pratiquées.",
"Le montant, les modalités et la perception effective de la participation ne figurent pas dans la source et ne sont pas chiffrés. Les soins antérieurs, autres cotisations et fondements autonomes restent distincts. Le financement et le solde public consolidé de la suppression ne sont pas établis.",
"Aucune charge nouvelle identifiée : pas d'attestation de ressources, contribution de remplacement ou formulaire nouveau ; l'affiliation et la prise en charge existantes continuent, sans supprimer les contrôles d'un autre fondement légal.",[
 effect('obligation_removed','personnes-ecrouees-fin-participation-speciale-frais-sante',
 "Supprimer la faculté de réclamer une participation sanitaire spéciale selon les ressources.",
 "Participation pouvant être demandée aux personnes écrouées dotées de ressources suffisantes ; aucun taux ou montant n'est fixé par la source.",
 "Aucune participation sur le fondement de L382-34 pour les soins futurs, quel que soit le montant des ressources ; aucune baisse chiffrée de taux revendiquée.",
 'legal_duty','Personnes écrouées et personnes retenues relevant du renvoi de L382-37 ; couverture des enfants conservée.',
 "Soins à compter de l'entrée en vigueur, même pour écrou ancien ; créances légales sur soins antérieurs et recours conservés.",
 "Aucune contribution ou déclaration de ressources de remplacement ; autres cotisations légalement autonomes hors champ.",
 "Une participation peut être demandée, lorsqu'elles disposent de ressources suffisantes, aux personnes écrouées assurées en vertu du premier alinéa.",
 "Aucune participation ne peut être demandée aux personnes écrouées sur le fondement du présent article au titre de la prise en charge des frais de santé prévue au premier alinéa, quel que soit le montant de leurs ressources.")]),xml34,["Participation facultative aux frais de santé mise à la charge des personnes écrouées disposant de ressources suffisantes."])

obj35=entry('L382-35',
"Maintien intégral indispensable des avantages : dispense d'avance, prise en charge de la part du régime, de la participation de L160-13 I et du forfait journalier ; maintien de la pension d'invalidité liquidée, capital-décès des ayants droit et maintien des indemnités journalières maternité déjà servies. L'article ne crée aucune formalité ou prélèvement accessoire à supprimer. Le capital-décès est une prestation, non un droit fiscal de succession.",
"Conserver les trois alinéas à leur place : L382-37 exclut expressément les deuxième et troisième pour les personnes retenues en centre de sûreté. La suppression de la participation spéciale de L382-34 ne supprime pas la prise en charge favorable du ticket modérateur et du forfait hospitalier ici prévue. Les conditions « liquidée » pour la pension et « bénéficiaires » pour les IJ maternité ne sont pas effacées ; elles n'interdisent pas les droits des futurs entrants remplissant ces conditions. Pas d'application du zéro d'indemnité ordinaire de première année aux prestations sociales.",
impact('retained_necessary',
"La source entière garantit l'accès aux soins sans avance et des continuités de prestations essentielles pendant l'écrou. Son maintien préserve cinq catégories d'avantages et la prestation décès ; aucune suppression de prélèvement supplémentaire n'est inventée.",
"La norme n'étend pas les mêmes continuités aux personnes exclues par L382-37 et ne crée pas de nouveau régime de liquidation. Le coût public des prestations et les conditions propres aux articles de prise en charge ne sont pas recalculés.",
"Aucune charge nouvelle identifiée : aucun certificat, demande périodique, condition d'emploi ni formalité liée à une succession n'est ajouté. Les conditions existantes et la dispense d'avance sont maintenues intégralement."))
obj35['benefit_review']="La dispense d'avance des frais, la couverture de la part du régime, du ticket modérateur de L160-13 I et du forfait journalier L174-4 sont toutes maintenues intégralement. La pension d'invalidité liquidée avant l'écrou continue d'être versée, les ayants droit conservent le capital-décès L361-1 et les personnes déjà bénéficiaires d'IJ maternité en conservent le versement pendant la détention. Ces droits restent ouverts aux futurs écrous remplissant les conditions ; la suppression fiscale des droits de succession n'abolit pas le capital-décès, qui est une prestation favorable. Les exclusions propres aux centres de sûreté de L382-37 ne sont pas étendues. La participation spéciale retirée à L382-34 ne remet en cause aucun de ces avantages."

entry('L382-36',
"Maintien nécessaire de la prise en charge par l'Etat de la prévention et de l'éducation pour la santé, des transports hospitaliers et des aménagements destinés aux personnes détenues. Ce sont des dépenses de service sanitaire, non des taxes privées ou formulaires redondants. La réserve des actions déjà financées par d'autres personnes publiques ou privées évite une double prise en charge sans supprimer les actions utiles.",
"Les 1°, 2° et 3° restent entiers, y compris la réserve et le renvoi historique à l'article 37 de la loi du 22 juillet 1983. Le texte intégral extérieur de cet article n'est pas fourni : ne pas inventer une recodification ni prétendre avoir clos sa concordance. La suppression de la participation sanitaire de L382-34 ne transfère pas silencieusement ces dépenses à l'assuré, à sa famille ou à un nouveau financeur.",
impact('retained_necessary',
"La source entière définit trois dépenses sanitaires dont la prise en charge publique est nécessaire à l'accès effectif aux soins en détention. Aucune obligation privée supplémentaire ou double déclaration n'est identifiée et la réserve des financements déjà assurés demeure.",
"Les coûts des transports, locaux et actions de prévention ainsi que la concordance de la loi extérieure de 1983 ne sont pas reconstitués. Une dépense maintenue n'est pas comptée comme économie et aucun transfert de financeur n'est revendiqué.",
"Aucune charge nouvelle identifiée : les catégories et financeurs existants sont conservés, sans nouvelle demande de subvention, inventaire, rapport ou contribution imposée aux personnes détenues."))

entry('L382-37',
"Maintien nécessaire du renvoi qui étend les règles sanitaires de la sous-section aux personnes retenues en centre socio-médico-judiciaire de sûreté tout en conservant les exclusions précises des deuxième et troisième alinéas de L382-35. Ce renvoi utile ne rétablit aucune participation supprimée : il applique pour l'avenir L382-34 dans sa rédaction allégée. Aucune réécriture stylistique ni seconde suppression de la participation n'est comptée.",
"La cible L382-35 fournie a été lue : le premier alinéa sanitaire est applicable, les alinéas de maintien de pension/capital-décès et d'IJ maternité sont exclus. Sa proposition reste nulle parce que l'article est maintenu en entier ; sa numérotation n'est pas déplacée. La transition de L382-34 traite expressément les personnes retenues. Aucun renvoi au droit privé de l'emploi n'est créé et aucune assimilation de la durée de rétention à un contrat de travail n'est admise.",
impact('retained_necessary',
"La disposition entière reste nécessaire pour ouvrir la couverture sanitaire et sa dispense d'avance aux personnes retenues dans le champ exact prévu. Le renvoi applique aussi l'allègement de L382-34 sans qu'une nouvelle réduction ou un nouveau corps soit nécessaire ici.",
"Les exclusions des deuxième et troisième alinéas de L382-35 subsistent ; leur extension n'est pas décidée. Le gain de participation est déjà porté par L382-34 et ne doit pas être recompté ; aucun coût national des centres n'est établi.",
"Aucune charge nouvelle identifiée : maintien d'un renvoi légal existant, sans déclaration de ressources, nouveau dossier d'emploi ou justification périodique. Les garanties sanitaires ne sont pas conditionnées à un renouvellement."))

entry('L382-38',
"Maintien nécessaire du débiteur opérationnel unique : l'Etat assure les déclarations et paiements sociaux pour le travail sous contrat d'emploi pénitentiaire. Le second alinéa prend en charge les cotisations et contributions salariales du service général, avantage à conserver pour les futurs travailleurs éligibles. Supprimer la déclaration sociale essentielle compromettrait l'affiliation et la preuve des droits ; aucun double dépôt distinct n'est prescrit par cet article.",
"Le contrat d'emploi pénitentiaire est un régime légal distinct du contrat privé unique ; la durée d'une affectation ou de la détention ne reçoit ici aucune règle de CDD. La suppression ciblée de la contribution autonomie dans L382-39 ne dispense pas de déclarer et payer les autres cotisations et contributions existantes. La note de l'ordonnance de 2022 et son plafond d'entrée au 1er décembre 2024 sont historiques et ne fixent pas la bascule du projet.",
impact('retained_necessary',
"Le texte officiel entier organise déjà une responsabilité déclarative et de paiement centralisée de l'Etat et une prise en charge favorable pour le service général. Aucune seconde fusion de déclarations ni suppression de cotisations n'est démontrée par son maintien.",
"Les financements effectifs, échanges de données et modalités réglementaires ne sont pas chiffrés. Les cotisations restant dues et leurs financeurs matériels relèvent aussi de L382-39 à L382-41 ; la prise en charge publique n'est pas une baisse nationale de prélèvement.",
"Aucune charge nouvelle identifiée : les déclarations existantes restent assurées par l'Etat sans formulaire personnel, registre ou attestation supplémentaire ; le service général conserve sa prise en charge salariale."))

xml39="""<p>La rémunération due aux personnes détenues qui exercent une activité de travail dans le cadre d'un contrat d'emploi pénitentiaire est assujettie aux cotisations de l'assurance maladie, maternité, invalidité et décès prévues à l'article L. 241-2, aux cotisations d'assurance vieillesse mentionnées à l'article L. 241-3 et aux cotisations au titre des accidents du travail et des maladies professionnelles fixées dans les conditions prévues au dernier alinéa de l'article L. 412-8. Les taux de ces cotisations sont déterminés par décret en Conseil d'Etat.</p>
<p>La contribution de solidarité pour l'autonomie prévue à l'article L. 137-40 n'est pas due sur ces rémunérations afférentes aux périodes de travail courant à compter de l'entrée en vigueur de la loi portant la présente rédaction. Aucune contribution de remplacement n'est instituée sur le fondement du présent article. Les cotisations et contributions afférentes aux périodes antérieures, leurs exonérations et autres dispositions plus favorables, créances, régularisations, restitutions, prescriptions et recours conservent leur régime, sans remboursement général des sommes légalement dues. Les droits sociaux constitués et les conditions d'ouverture des prestations ne sont pas réduits du fait de cette seule suppression.</p>"""
entry('L382-39',
"Réforme de fond ciblée : retrait de la contribution accessoire de solidarité pour l'autonomie sur les rémunérations du contrat d'emploi pénitentiaire, sans prélèvement de remplacement. Ce prélèvement patronal de financement général de l'autonomie n'ouvre pas un droit individuel propre proportionné à la rémunération pénitentiaire. Les cotisations maladie, maternité, invalidité, décès, vieillesse et AT-MP finançant la protection du travailleur sont intégralement maintenues avec leurs renvois. La suppression bénéficie au redevable patronal ou à l'Etat dans son champ de prise en charge ; elle n'est pas présentée comme une hausse automatique du net du détenu.",
"L137-40 lu dans le corpus fixe le taux général de 0,3 % sur la même assiette que les cotisations patronales maladie ; la dérogation est explicite et limitée aux rémunérations pénitentiaires futures, sans supprimer la contribution des autres employeurs. R382-132 à R382-135 lus : maladie à 4,20 %, vieillesse par renvoi L241-3, AT-MP par renvois L242-5 à L242-7-1 et précompte salarial ne sont pas modifiés. L382-40 conserve l'assiette et son plancher vieillesse favorable aux droits ; L382-41 est coordonné pour les contributions anciennes. L382-38 reste applicable pour la déclaration et le paiement des autres prélèvements. L412-8 dernier alinéa garde ses prescriptions spéciales ; le contrat pénitentiaire et l'employeur public ne sont pas incorporés à la capitalisation privée. La perte brute de recettes autonomie, l'effet des dépenses publiques moindres et le financement de la branche restent à établir dans les textes financiers compétents, sans recette compensatrice présumée.",
impact('material_reduction',
"Par rapport à la source entière, une seule contribution disparaît dans le champ du travail sous contrat d'emploi pénitentiaire. Les cotisations assurantielles et les droits restent maintenus. Le taux général documenté est 0,3 % de l'assiette patronale maladie ; cette abolition sectorielle n'est ni la suppression nationale de la CSA ni un transfert vers la capitalisation.",
"La suppression ne couvre que les rémunérations des périodes de travail nouvelles sous contrat pénitentiaire ; les dettes anciennes et autres activités demeurent. Aucun montant national, compensation durable ou solde public net n'est établi ; une dépense de l'Etat moindre peut réduire la perte consolidée sans l'annuler par présomption.",
"Aucune charge nouvelle identifiée : pas de taux de remplacement, contribution, justificatif d'exonération, agrément ou déclaration distincte. Le régime de paie existant applique directement la dispense et conserve ses informations nécessaires aux autres droits.",[
 effect('tax_removed','travail-penitentiaire-suppression-contribution-autonomie',
 "Supprimer la CSA sur les rémunérations des périodes nouvelles de travail sous contrat d'emploi pénitentiaire.",
 "Assujettissement exprès à la CSA de L137-40, au taux général de 0,3 % sur l'assiette des cotisations patronales maladie ; rémunérations retenues selon L382-40 et L242-1.",
 "Aucune CSA sur ces rémunérations afférentes aux périodes nouvelles ; le taux et l'assiette des autres cotisations et la CSA hors de ce champ restent distincts.",
 'percent',"Donneurs d'ordre redevables des contributions patronales du travail pénitentiaire, dont l'Etat lorsqu'il en supporte la charge.",
 "Périodes de travail à compter de l'entrée en vigueur ; ancien principal et avantages, régularisations, restitutions et recours préservés.",
 "Aucun prélèvement, taux ni déclaration d'exonération de remplacement ; aucune baisse automatique de la part salariale revendiquée.",
 "à la contribution de solidarité pour l'autonomie prévue à l'article L. 137-40",
 "La contribution de solidarité pour l'autonomie prévue à l'article L. 137-40 n'est pas due sur ces rémunérations afférentes aux périodes de travail courant à compter de l'entrée en vigueur de la loi portant la présente rédaction.")]),xml39,["Assujettissement des rémunérations des périodes nouvelles de travail pénitentiaire à la contribution patronale de solidarité pour l'autonomie."])

entry('L382-40',
"Maintien intégral nécessaire de l'assiette des cotisations pénitentiaires et du plancher de vieillesse de base. Ce plancher accroît la base cotisée et les droits correspondants lorsque la faible rémunération ne l'atteint pas ; le retirer indistinctement supprimerait une protection tandis que l'assurance vieillesse demeure. La contribution autonomie supprimée à L382-39 n'est pas rétablie par le renvoi aux cotisations qui y restent mentionnées.",
"L242-1 entier et sa proposition ont été lus : conserver les exclusions applicables dans leur champ, notamment épargne et indemnités éligibles, sans créer d'indemnité privée de rupture pour le contrat pénitentiaire. Le second alinéa vise les seules cotisations vieillesse de base et ne doit pas devenir un plancher de toutes cotisations. L382-41 continue la prise en charge patronale vieillesse par l'Etat, L382-38 celle du service général. La réforme de capitalisation des salariés privés et le préavis individuel de quinze jours ne modifient pas cette assiette spéciale. Note historique de l'ordonnance 2022 conservée dans son champ.",
impact('retained_necessary',
"La source entière fixe l'assiette et une garantie de cotisation vieillesse sur une base minimale. Elle ne constitue pas une seconde contribution autonomie et son maintien protège les droits associés aux faibles rémunérations plutôt que créer une nouvelle obligation documentaire.",
"Le montant réglementaire du plancher, le partage exact des cotisations et le rendement de retraite individuel ne sont pas chiffrés. La dispense de CSA est portée par L382-39 et ne doit pas être recomptée ici ; le contrat privé unique reste hors champ.",
"Aucune charge nouvelle identifiée : maintien de l'assiette, du plancher existant et des exclusions légales applicables, sans justificatif ou attestation de salaire nouveau et sans transfert imposé à un compte de capitalisation."))

xml41="""<p>Les cotisations patronales prévues à l'article L. 382-39 sont à la charge des donneurs d'ordre mentionnés au 1° et au 2° de l'article L. 412-3 du code pénitentiaire, à l'exception des cotisations patronales d'assurance vieillesse qui sont prises en charge par l'Etat.</p>
<p>Les contributions patronales afférentes aux périodes de travail antérieures à l'entrée en vigueur de la suppression prévue à l'article L. 382-39 demeurent à la charge des donneurs d'ordre dans les conditions antérieures. Leurs exonérations et autres dispositions plus favorables, créances, régularisations, restitutions, prescriptions et recours conservent leur régime. Le présent article ne peut fonder le rétablissement de la contribution de solidarité pour l'autonomie sur les rémunérations afférentes aux périodes nouvelles. La prise en charge des cotisations et contributions salariales du service général prévue à l'article L. 382-38 demeure applicable dans son champ.</p>"""
entry('L382-41',
"Coordination nécessaire de la suppression ciblée de la contribution autonomie à L382-39 : la règle active de répartition vise les cotisations patronales subsistantes et maintient l'exception vieillesse financée par l'Etat. Les contributions des anciennes périodes restent à la charge de leur redevable d'origine avec leurs avantages et recours. Il n'y a ni nouvelle suppression distincte ni transfert de la dette à la personne détenue.",
"Le renvoi source est explicitement le 1° et le 2° de L412-3 du code pénitentiaire. La cible fournie L412-3 du code de la sécurité sociale concerne au contraire l'intérim et ne peut pas lui être substituée ; concordance externe non validée en l'absence du texte pénitentiaire intégral. Aucun nouveau renvoi à une cible absente n'est créé : le renvoi externe source est conservé. La dispense de CSA relève de la même clé que L382-39. La prise en charge patronale vieillesse et la prise en charge salariale du service général restent à leur champ. La note d'entrée au plus tard le 1er décembre 2024 concerne l'ancienne ordonnance, pas la date du projet.",
impact('coordination_only',
"La source entière est coordonnée pour répartir les seules cotisations patronales subsistantes, conserver les contributions anciennes et empêcher la réintroduction de la CSA supprimée à L382-39. La prise en charge vieillesse de l'Etat est conservée ; aucune seconde taxe supprimée ni baisse de financement nouvelle n'est comptée.",
"Le contenu intégral de L412-3 pénitentiaire n'est pas fourni et la cible homonyme CSS ne prouve pas sa concordance. Le coût des prises en charge publiques n'est pas recalculé et la perte de CSA est recensée exclusivement sous la mesure de L382-39.",
"Aucune charge nouvelle identifiée : aucun financeur nouveau, formulaire d'exonération ou déclaration ne remplace la contribution retirée. Les redevables anciens et la prise en charge publique existante sont maintenus sans dette transférée au détenu.",[
 effect('coordination','travail-penitentiaire-suppression-contribution-autonomie',
 "Coordonner le financeur des cotisations restantes et des contributions anciennes avec la suppression sectorielle de la CSA.",
 "Cotisations et contributions patronales de L382-39 à la charge des donneurs d'ordre, sauf vieillesse prise en charge par l'Etat.",
 "Cotisations restantes selon la même répartition ; contributions antérieures conservées ; absence de rétablissement de la CSA nouvelle.",
 'financing',"Donneurs d'ordre du travail pénitentiaire et Etat assurant les prises en charge existantes.",
 "Même date et mêmes périodes de travail que L382-39 ; garanties et dettes anciennes conservées.",
 "Aucune nouvelle procédure ni transfert de financeur ; simple coordination de la même mesure de CSA.",
 "Les cotisations et contributions patronales prévues à l'article L. 382-39 sont à la charge des donneurs d'ordre mentionnés au 1° et au 2° de l'article L. 412-3 du code pénitentiaire, à l'exception des cotisations patronales d'assurance vieillesse qui sont prises en charge par l'Etat.",
 "Les cotisations patronales prévues à l'article L. 382-39 sont à la charge des donneurs d'ordre mentionnés au 1° et au 2° de l'article L. 412-3 du code pénitentiaire, à l'exception des cotisations patronales d'assurance vieillesse qui sont prises en charge par l'Etat.")]),xml41)

entry('L382-42',
"Maintien intégral nécessaire de la prise en charge sociale des personnes détenues en stage de formation professionnelle. Le renvoi à L6342-3 du code du travail assure le calcul forfaitaire et la prise en charge intégrale par le financeur de formation, y compris les fonds handicap selon leurs règles. La durée du stage est pédagogique ; elle ne fixe pas la durée d'un contrat d'emploi et ne recrée aucun nouveau CDD.",
"L6342-3 du travail a été lu intégralement dans le corpus public : Etat, opérateur de compétences ou région selon le financement ; fonds handicap pour les formations qu'ils financent ou cofinancent ; taux forfaitaires révisés annuellement selon le plafond. Ces avantages restent ouverts aux futurs stages éligibles, rémunérés ou non, sans nouvelle attestation ou condition de contrat unique. Le régime de stagiaire distinct ne doit pas être remplacé par la rémunération pénitentiaire de L382-39. Note de l'ordonnance de 2022 maintenue comme historique.",
impact('retained_necessary',
"La source entière garantit un financement social favorable pendant les stages des personnes détenues, par renvoi au régime des stagiaires. Supprimer ce renvoi retirerait la couverture et la prise en charge, sans formalité indépendante ou prélèvement accessoire identifié.",
"Le coût des cotisations forfaitaires et le nombre de stagiaires ne sont pas chiffrés. Le stage n'est pas assimilé à une relation de travail privée ; les dispositifs d'aide et les financeurs conservent leur champ propre, sans promesse de capitalisation.",
"Aucune charge nouvelle identifiée : le calcul et la prise en charge existants demeurent, sans déclaration individuelle supplémentaire, nouveau contrat d'emploi ou justificatif de durée minimale."))

# Les analyses ci-dessous portent exclusivement sur les cibles requises, et non
# sur les seuls numéros homonymes ou sur les propositions comme droit en vigueur.
common = {
'L382-21-1': {
'L1234-1': "L1234-1 vise le préavis de licenciement d'un salarié privé ; les IJ des ministres des cultes n'en dépendent pas. Les quinze jours proposés, sans condition d'ancienneté et avec transition des anciens contrats, ne deviennent ni une carence maladie ni un délai de paiement. Les procédures collectives et protections distinctes restent étrangères à ce renvoi social.",
'L1221-2': "L1221-2 proposé institue le contrat privé nouveau à durée indéterminée ; l'activité cultuelle indemnisée n'est pas transformée en emploi salarié par L382-21-1. La durée d'un arrêt ou d'un congé ne fixe pas un terme d'emploi. Les contrats privés éventuellement exercés à côté conservent leurs propres transitions et avantages.",
'L1234-9': "L1234-9 proposé règle l'indemnité ordinaire patronale du contrat privé : un an au terme effectif préavis inclus, 0,20 mois par année totale, mois complets au prorata et plafond de six mois. Ces règles, et la notification de rupture, ne conditionnent ni IJ maladie ni maternité des cultes ; salaires, congés et indemnités spéciales restent distincts."},
'L382-25': {
'L1234-1': "Le financement forfaitaire vieillesse des cultes ne fixe aucun préavis de salarié. Les quinze jours calendaires proposés à L1234-1 pour les nouveaux contrats privés ne remplacent pas une échéance de cotisation ni une procédure de fixation des taux ; anciens contrats et procédures collectives restent à leur champ.",
'L1221-2': "Le contrat privé unique proposé par L1221-2 ne définit pas les fonctions cultuelles ni leurs cotisations forfaitaires. Les éventuelles durées d'apprentissage citées par la cible de financement L222-2-1 restent des périodes pédagogiques, sans fin automatique d'un emploi nouveau ni fermeture d'aides futures.",
'L1234-9': "L'indemnité de L1234-9 proposée après un an, ancienneté totale au terme effectif incluant le préavis, 0,20 mois par année et plafond de six mois, ne s'applique pas au montant des cotisations des cultes. Leurs bases et la répartition contributive ne deviennent pas des indemnités de rupture ; droits d'anciens contrats distincts."},
'L382-27': {
'L1234-1': "La liquidation vieillesse des cultes ne résulte pas du préavis privé de L1234-1. Le préavis de quinze jours proposé pour les nouveaux contrats, ses notifications et les règles antérieures conservées ne modifient ni l'âge de retraite ni les périodes historiques antérieures à 1998 visées ici.",
'L1221-2': "Le renvoi aux pensions générales dans L382-27 ne transforme pas le ministère religieux en contrat privé unique. L1221-2 proposé interdit les nouveaux termes d'emploi mais ne limite pas les périodes d'assurance ; formations et anciennes périodes demeurent admissibles selon les textes de pension.",
'L1234-9': "Le seuil d'un an au terme effectif, préavis inclus, le calcul sur toute l'ancienneté à 0,20 mois et le plafond de six mois proposés à L1234-9 concernent l'indemnité ordinaire privée. Ils n'écrêtent ni pension, minimum, réversion ou majoration des cultes ; les huit mois et droits anciens restent dans la transition du contrat privé."},
'L382-29': {
'L1234-1': "La liste de L382-29 porte sur gestion, cotisations, garanties et recours sociaux, pas sur le licenciement privé. Le préavis de quinze jours proposé par L1234-1 ne remplace ni le mois de mise en demeure sociale ni les délais de recours et prescription ; notifications et contrats antérieurs restent distincts.",
'L1221-2': "L382-29 ne crée aucun contrat et ses renvois de rachat ou de remboursement ne rétablissent pas un CDD. Le contrat unique de L1221-2 proposé régit seulement les nouvelles relations privées ; l'assistance au recouvrement et les conventions anciennes gardent les transitions de leurs textes propres.",
'L1234-9': "L'indemnité privée proposée à L1234-9, zéro avant un an au terme effectif puis 0,20 mois par année totale avec prorata des mois complets et plafond de six mois, n'est pas une limite de remboursement ou de remise sociale. Aucun renvoi de L382-29 n'y subordonne ses garanties ni les droits aux prestations."},
'L382-29-1': {
'L1234-1': "La période de formation rachetable de L382-29-1 n'est pas un préavis de salarié privé. Les quinze jours calendaires proposés par L1234-1 et leur notification ne conditionnent pas le rachat ; les formations précédant l'affiliation restent couvertes sans condition d'ancienneté d'emploi ajoutée.",
'L1221-2': "Le contrat unique de L1221-2 proposé ne fait pas d'une formation religieuse un contrat de travail. Une formation peut rester limitée dans le temps sans limiter l'emploi éventuellement associé ; le rachat demeure ouvert aux futures périodes éligibles comme aux anciennes, sans nouveau CDD.",
'L1234-9': "L1234-9 proposé calcule une indemnité privée après un an au terme effectif préavis inclus, sur toute l'ancienneté à 0,20 mois par année, fractions en mois complets, plafond six mois. Ce seuil ne devient pas une durée minimale de formation ou de rachat vieillesse ; aucune indemnité n'est créée par la formation cultuelle."},
'L382-31': {
'L1234-1': "Un mandat local et son indemnité de fonction ne sont pas un contrat privé. Les quinze jours proposés à L1234-1 ne régissent ni la fin du mandat ni la demande d'assujettissement volontaire ; une éventuelle suspension d'emploi privé de l'élu demeure à son champ et à sa transition propres.",
'L1221-2': "L1221-2 proposé s'applique aux emplois privés nouveaux, pas au mandat électif visé par L382-31. Les renvois CGCT relatifs à la cessation d'activité ne créent pas de CDD ni de contrat unique pour l'élu ; la couverture et l'option sous seuil restent ouvertes aux futurs élus éligibles.",
'L1234-9': "Le zéro avant un an puis 0,20 mois par année totale au terme effectif préavis inclus, prorata en mois complets et plafond de six mois proposés par L1234-9 ne s'appliquent pas à une indemnité de fonction élective. Les anciens droits d'emploi et réparations éventuelles ne sont ni remplacés ni limités par l'affiliation sociale de l'élu."},
'L382-35': {
'L1234-1': "L1234-1 est le préavis de licenciement privé ; son projet de quinze jours ne conditionne pas la dispense d'avance ni le maintien des prestations pendant l'écrou. Une notification d'emploi et l'ancienneté du salarié ne deviennent pas des conditions sanitaires supplémentaires ; anciens contrats et procédures collectives restent distincts.",
'L1221-2': "Le contrat privé unique de L1221-2 proposé ne subordonne pas la protection de L382-35 à un emploi détenu ou extérieur. Les soins, pensions déjà liquidées, capital-décès et IJ maternité restent dans leur champ, pour les écrous futurs aussi ; aucune durée de détention ne crée un nouveau CDD.",
'L1234-9': "L1234-9 proposé limite l'indemnité ordinaire privée après un an au terme effectif préavis inclus, à 0,20 mois par année totale, fractions de mois complets et plafond six mois. Ce zéro de première année n'efface ni pension d'invalidité, capital-décès, IJ maternité, ni prise en charge sanitaire de L382-35."},
'L382-37': {
'L1234-1': "La rétention en centre de sûreté n'est pas une rupture de contrat privé ; le préavis proposé de quinze jours à L1234-1 n'est pas un délai de rétention ou de prise en charge médicale. Le renvoi sanitaire de L382-37 n'ajoute donc aucune notification ni condition d'ancienneté d'emploi.",
'L1221-2': "L1221-2 proposé régit les nouvelles embauches privées et ne fixe pas la durée de la rétention de sûreté. L382-37 étend des protections sanitaires, pas un contrat d'emploi ; il ne rétablit aucun CDD spécial ni ne ferme la couverture des futurs retenus remplissant les conditions existantes.",
'L1234-9': "Le barème proposé de L1234-9, un an au terme effectif préavis inclus puis 0,20 mois par année totale et plafond six mois avec fractions en mois complets, ne s'applique pas aux frais de santé d'une personne retenue. Les exclusions des alinéas de L382-35 restent légales et distinctes d'une indemnité de rupture privée."},
'L382-39': {
'L1234-1': "Le contrat d'emploi pénitentiaire est un régime distinct ; L1234-1 du travail, dans sa source et sa proposition de quinze jours pour le contrat privé nouveau, ne fixe pas sa rupture. La suppression de CSA ne modifie ni notification pénitentiaire, ni autorisation, ni ancienneté ; elle ne promet pas une procédure pénitentiaire complète en quinze jours.",
'L1221-2': "La règle de contrat privé unique proposée à L1221-2 n'est pas attribuée artificiellement au contrat d'emploi pénitentiaire de L382-39. La suppression d'une contribution sociale n'autorise aucun CDD privé nouveau et ne change pas les durées légales propres à l'affectation ou au travail pénitentiaire.",
'L1234-9': "Le seuil privé d'un an au terme effectif avec préavis, l'indemnité de 0,20 mois par année totale, fractions de mois complets et plafond six mois proposés par L1234-9 ne deviennent pas un droit ou une exonération de rupture pénitentiaire. Les cotisations restantes ne dépendent pas de ce barème et les régimes spéciaux restent distincts."},
'L382-40': {
'L1234-1': "Le calcul des cotisations pénitentiaires sur rémunération et plancher vieillesse ne dépend pas d'un préavis de licenciement privé. Les quinze jours proposés par L1234-1, et le maintien des anciens contrats, n'autorisent ni prorata nouveau de l'assiette ni suppression des garanties de retraite ; notifications distinctes.",
'L1221-2': "L1221-2 proposé ne convertit pas le contrat d'emploi pénitentiaire en contrat privé unique. Le renvoi de L382-40 à une assiette de revenus d'activité ne qualifie pas l'emploi et ne rétablit aucun CDD ; il conserve les conditions et exclusions de calcul sans nouvelle formalité d'embauche.",
'L1234-9': "Le barème ordinaire privé de L1234-9 proposé, un an à la fin effective incluant le préavis, 0,20 mois par année totale, fractions en mois complets et plafond six mois, ne définit pas la rémunération ni le plancher cotisé des personnes détenues. Les exclusions d'indemnités de L242-1 restent seulement applicables aux sommes qui remplissent leurs propres conditions."},
'L382-41': {
'L1234-1': "L382-41 répartit la charge patronale pénitentiaire et ne vise pas la rupture d'un contrat privé. Les quinze jours proposés à L1234-1 ne deviennent pas un délai de versement de cotisations ; notifications et procédures collectives ou protégées d'un emploi privé restent distinctes et non supprimées.",
'L1221-2': "Le contrat privé unique de L1221-2 proposé ne remplace pas le contrat pénitentiaire par la seule désignation d'un donneur d'ordre. La répartition conservée entre donneurs d'ordre et Etat ne crée ni nouveau CDD privé ni terme automatique d'emploi privé lié à la mission ou à la détention.",
'L1234-9': "La prise en charge patronale vieillesse par l'Etat n'est pas l'indemnité de L1234-9. Le seuil proposé d'un an au terme effectif préavis inclus, le calcul de 0,20 mois sur l'ancienneté totale et le plafond six mois avec mois complets ne modifient aucun financeur social ni droit propre au régime pénitentiaire."},
'L382-42': {
'L1234-1': "Un stage de formation de personne détenue n'est pas un licenciement privé. Le préavis de quinze jours proposé à L1234-1 ne fixe ni durée de stage ni délai de prise en charge sociale ; le stage et la couverture restent régis par L6342-3, sans condition d'ancienneté ou de notification privée ajoutée.",
'L1221-2': "L1221-2 proposé distingue expressément la durée de formation de la durée de l'emploi privé. Le stage visé par L382-42 peut conserver sa durée pédagogique et ses cotisations prises en charge sans rétablir un CDD ni mettre automatiquement fin à un éventuel contrat privé nouveau. Les futures formations éligibles restent couvertes.",
'L1234-9': "L'indemnité ordinaire privée proposée à L1234-9, zéro avant un an à la fin effective avec préavis puis 0,20 mois par année totale et plafond six mois avec prorata des mois complets, n'est pas une condition de financement du stage. Le zéro avant un an n'efface ni prestations ni prise en charge des cotisations du stagiaire."}
}

specific={
('L382-21-1','L331-3'): "Le II renvoie à l'indemnité maternité : six semaines avant/dix après, huit semaines de cessation minimale, multiples et prématurité/hospitalisation avec leurs durées propres demeurent. Il ne s'agit pas d'ancienneté de contrat ni de préavis ; aucune durée de congé ou majoration favorable n'est retranchée, y compris pour les futures naissances éligibles.",
('L382-21-1','L331-5'): "Le renvoi du II conserve le report de la période restante après hospitalisation de l'enfant jusqu'à la sixième semaine, la réserve de période supplémentaire L331-3 et les deux semaines supplémentaires sur prescription médicale. Ces durées médicales et maternité ne deviennent ni un préavis privé ni une fin de contrat.",
('L382-21-1','L323-7'): "La source impose un avis préalable après une suspension suivie d'une prescription rapprochée. La proposition l'abroge uniquement pour les prescriptions nouvelles : L382-21-1 limite désormais ce renvoi aux prescriptions anciennes et reprend l'absence de visa automatique pour les nouvelles, sans annuler suspension antérieure ni contrôles médicaux justifiés.",
('L382-21-1','L331-6'): "Le II conserve l'indemnisation du père après décès de la mère pour la période restante, sans conditions de L313-1, le report possible et le droit subsidiaire du conjoint, partenaire ou concubin. Le décès est ici un fait ouvrant une prestation, non un impôt de succession ; aucun seuil d'ancienneté du contrat unique n'est ajouté.",
('L382-21-1','L323-1'): "Le I vise la carence, son point de départ et la durée maximale de service maladie, avec distinction des affections relevant de L324-1 et des autres. La suppression de la durée d'affiliation ne supprime pas ces limites ni ne les remplace par le préavis privé ; la carence réglementaire spéciale des cultes doit rester distinguée de l'affiliation.",
('L382-21-1','L313-1'): "Le renvoi source au dernier alinéa désignait la durée minimale du II. La proposition ajoute un III et retire cette condition autonome pour les nouvelles périodes. L382-21-1 supprime expressément sa propre condition spéciale, même pour le début d'indemnisation, au lieu d'attribuer automatiquement le régime des salariés aux cultes ; le renvoi ordinal devenu inadapté disparaît. Même transition par périodes et aucune preuve de remplacement ; autres conditions propres et dérogations plus favorables conservées.",
('L382-21-1','L331-8'): "Le II maintient paternité et accueil : limite vingt-cinq jours ou trente-deux en naissances multiples, cessation minimale de quatre jours, hospitalisation et non-cumuls dans leur champ. La poursuite du mandat local et l'indemnité attachée à l'activité salariée restent distinctes ; le préavis de quinze jours et l'indemnité ordinaire privée ne remplacent aucune de ces durées.",
('L382-21-1','L331-7'): "Le II conserve l'adoption : seize semaines au plus, vingt-deux en adoptions multiples, dix-huit dans le cas de trois enfants au moins, cessation d'activité et fractionnement propres. La règle des élus poursuivant ou interrompant leur mandat reste dans son champ. Aucun contrat à durée déterminée ni seuil d'un an d'emploi n'est nécessaire pour préserver ces droits futurs.",
('L382-21-1','L162-4-1'): "Le premier alinéa vise la justification médicale de l'incapacité par le prescripteur. La cible conserve les éléments médicaux et l'authentification, le plafond réglementaire au moins un mois pour la prescription initiale et deux pour la prolongation, et la dérogation médicale motivée. Ni cette dérogation favorable ni le secret médical ne sont remplacés par une notification d'employeur.",
('L382-24','L351-1'): "L351-1 est le cadre de liquidation vieillesse ; le renvoi direct de L382-24 reste L351-1-5 pour l'âge abaissé d'inaptitude/incapacité. La proposition de L351-1 réserve le transfert aux salariés privés, pas automatiquement aux cultes. Le passage invalidité-vieillesse et le droit à tierce personne ne sont ni reportés à l'âge ordinaire ni soumis à un an d'ancienneté privée.",
('L382-25','L222-2-1'): "Le 4° du I maintient le concours de la branche dans les conditions de L222-2-1. Cette cible définit des financements de solidarité, dont périodes assimilées et apprentissage ; sa proposition conserve les aides pour les relations privées futures sans confondre durée pédagogique et durée d'emploi. Le renvoi de financement ne crée ni CDD, ni préavis, ni transfert automatique des cultes en capitalisation.",
('L382-27','L351-1'): "Le premier alinéa rend le cadre de liquidation et de calcul vieillesse applicable aux cultes, avec droits antérieurs et minimum historique. Le dernier alinéa proposé à L351-1 limite le transfert de cotisations aux salariés du régime général employés par une personne privée : il ne réduit pas automatiquement les droits cultuels ni leurs périodes antérieures à 1998.",
('L382-27','L355-3'): "L355-3 vise les indus de vieillesse et d'invalidité : prescription de deux ans hors fraude/fausse déclaration, non-récupération de bonne foi sous le plafond et examen amiable dans la tranche jusqu'au double, garanties de retenue. Le renvoi maintient toutes ces protections ; ni quinze jours privés ni plafond d'indemnité de six mois ne les remplacent.",
('L382-27','L351-10'): "L351-10 porte le minimum contributif à taux plein, sa majoration contributive et les périodes de solidarité dans leurs limites, l'ajout des majorations de handicap/enfants/conjoint et surcote, ainsi que sa revalorisation au 1er janvier au moins comme le SMIC. Le renvoi entier est maintenu sans fermer l'avantage aux futurs liquidants ni relever un seuil d'emploi privé.",
('L382-27','L351-3'): "L382-27 vise expressément les seuls 4°, 5° et 6° : service national, situations de guerre après le 1er septembre 1939 et détention provisoire non imputée à la peine sous condition d'assurance antérieure. Les autres catégories de la cible ne sont pas importées par ce renvoi. Aucun seuil d'ancienneté du contrat unique ne remplace ces conditions propres.",
('L382-29','L231-12'): "Le renvoi vise la gratuité du mandat d'administrateur, avec remboursements de déplacement et des salaires maintenus aux employeurs, ainsi qu'indemnités possibles des indépendants. La proposition cible reformule ces mêmes garanties ; L382-29 ne supprime ni rémunération maintenue ni remboursement et ne remplace pas l'absence pour mandat par un préavis de rupture.",
('L382-29','L355-3'): "La cible maintient la prescription de deux ans des indus, sauf fraude/fausse déclaration, la protection de bonne foi sous plafond, le recours amiable jusqu'au double et les limites des retenues croisées. Ces protections restent applicables aux prestations des cultes via L382-29 ; la coordination d'abrogations pénales ne ferme aucune remise ni recours.",
('L382-29','L351-14-1'): "Le renvoi conserve rachat volontaire dans la limite totale de douze trimestres, neutralité actuarielle et réductions II à IV propres à leurs catégories. La proposition cible retire seulement la catégorie administrative d'établissement pour les demandes nouvelles et en cours ; L382-29 ne la rétablit pas, ne crée aucun CDD et préserve les anciens versements et droits acquis.",
('L382-29','L243-5'): "L243-5 remet les accessoires et frais dus au jugement d'ouverture de sauvegarde, redressement ou liquidation, sauf passif issu du travail dissimulé L8221-1. La cible conserve cet avantage, applicable selon sa note au 1er juillet 2026 ; le renvoi entier reste valide, sans confondre travail dissimulé et existence d'un ancien CDD ni exiger un an d'emploi pour la remise.",
('L382-29','L244-9'): "La cible concerne la contrainte sociale : opposition judiciaire, exécution provisoire limitée au travail illégal après deux jours calendaires et possibilité d'arrêt, puis prescription de trois ans de la contrainte définitive. Le renvoi est maintenu sans substituer le préavis de quinze jours à ces délais ; sa note d'entrée différée au plus tard au 1er janvier 2027 n'est pas une date de promulgation du projet.",
('L382-29-1','L351-14-1'): "L382-29-1 vise exactement les périodes du 1° du I pour y assimiler la formation précédant le statut cultuel ; les douze trimestres globaux et conditions de rachat restent applicables. La proposition cible supprime la catégorie administrative d'établissement pour demandes nouvelles ou en cours, sans supprimer les conditions de diplôme ou de scolarité assimilée ni réserver les avantages aux anciens contrats. Les réductions II à IV gardent leurs critères propres.",
('L382-31','L3123-7'): "La cible fournie est L3123-7 du code du travail et traite le temps partiel, minimum conventionnel et dispenses, dont jeunes étudiants et âge de retraite progressive. L382-31 vise explicitement L3123-7 du CGCT, relatif à l'élu : ce n'est pas la même cible. Aucune substitution n'est faite ; le retrait du plancher privé de vingt-quatre heures ne modifie pas l'assujettissement des indemnités de mandat.",
('L382-31','L241-3'): "Le premier alinéa renvoie uniquement à la valeur du plafond de sécurité sociale, annuel et non décroissant selon L241-3. Les fractions fixées par décret et l'option des élus restent inchangées. Les II et suivants proposés de L241-3 concernent la capitalisation des salariés d'employeurs privés : ils ne sont pas importés dans le mandat ni dans ses indemnités par ce renvoi de valeur.",
('L382-37','L382-35'): "L382-35 fourni comporte trois alinéas : le premier donne la dispense d'avance et la couverture sanitaire ; le deuxième maintient invalidité et capital-décès ; le troisième les IJ maternité. L382-37 exclut exactement les deuxième et troisième pour les personnes retenues. Le maintien intégral de L382-35 conserve cette numérotation et ne ferme pas les droits sanitaires des futurs retenus.",
('L382-39','L241-3'): "Le renvoi maintient les cotisations vieillesse et leur distinction plafonnée/déplafonnée ; la CSA supprimée est distincte. Les II et suivants proposés de L241-3 limitent le transfert aux salariés employés par une personne de droit privé, sous conditions préalables : le contrat pénitentiaire et la prise en charge patronale par l'Etat ne sont pas assimilés automatiquement à ce champ.",
('L382-39','L412-8'): "Le renvoi vise exactement le dernier alinéa de L412-8 qui permet de fixer les obligations d'employeur et les bases spéciales pour rémunérations absentes ou non normales, avec le 5° relatif au travail pénitentiaire et le 2° c pour les formations dans leurs champs. Ces prescriptions et l'exception de séjour du 5° ne sont pas effacées par la suppression de CSA ; aucun contrat privé nouveau n'est créé.",
('L382-40','L242-1'): "Le renvoi porte sur le calcul de la rémunération cotisable, non sur la qualification de salarié privé. Le I de L242-1 rattache les revenus à leurs périodes et son II conserve les exclusions ; la proposition cible allège les assujettissements intégraux de fortes indemnités sans supprimer leurs limites propres. L382-40 ne crée pas de droit à une indemnité de L1234-9 et son minimum vieillesse reste limité à ce seul risque.",
('L382-41','L412-3'): "La cible fournie est L412-3 du CSS, qui concerne prévention, risques et recours entre entreprises de travail temporaire et utilisatrices. Le renvoi source vise les 1° et 2° de L412-3 du code pénitentiaire, autre code et autre objet. Cette cible homonyme ne prouve aucune concordance : le renvoi pénitentiaire est conservé sans lui substituer l'intérim ni le contrat unique ; le texte externe intégral manque ici."
}

for s in sources:
    n=s['number'];key=s['code_id']+'|'+s['source_id']; checks=[]
    for tk in refs['requirements'][key]:
        t=refs['targets'][tk];tn=t['number']
        a=common.get(n,{}).get(tn) or specific.get((n,tn))
        if not a:raise ValueError(('Analyse de référence manquante', n, tn))
        checks.append(dict(target_key=tk, view_sha256=t['view_sha256'], assessment=a))
    if checks:
        result[n]['reference_checks']=checks
    if s.get('benefit_check_required') and 'benefit_review' not in result[n]:
        raise ValueError(('Analyse des avantages manquante', n))

answer=[result[s['number']] for s in sources]
Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2)+'\n')
print('answer.json:',len(answer),'articles;',sum(a['status']=='rewrite_draft' for a in answer),'nouveaux corps;',sum(a['status']=='retained_unchanged' for a in answer),'maintiens intégraux')
